#!/usr/bin/env bash
set -Eeuo pipefail

STAMP="$(date +%Y%m%d-%H%M%S)"
ROOT="/mnt/SDCARD/data/ports/openmw51"
BIN="$ROOT/bin/openmw-0.51"
LUA="$ROOT/mods/TSPInteriorVisGrid/scripts/TSPInteriorVisGrid/visgrid.lua"
TOPO="$ROOT/mods/TSPInteriorVisGrid/scripts/TSPInteriorVisGrid/topology.lua"

PKG="$HOME/Downloads/openmw51-visgrid-v18-room-traversal-$STAMP"
LOG="$PKG/install.log"

V17_SHA="299c6cf709a029adf02c25e52155c71b39b5ba2e32c4bdc7b1c4f34d9a9081b3"
V18_SHA="b0fec851738ad4aed67664750e391efad232bf8a8ce86582594e4b619e5b0933"
BIN_SHA="ce235c9e4cf1f4441106fd5445772710e072bf1c73c93a6cd409fdcd11e8caf3"
TOPO_SHA="24a6989dacc1149a2a3895da371e56e52d370348d01ea0a5403f4e20755bef6b"

mkdir -p "$PKG/device-backup"

if [ -f "$HOME/Downloads/visgrid-tools/device.env" ]; then
    . "$HOME/Downloads/visgrid-tools/device.env" || true
fi
if [ -n "${TSP_DEV:-}" ]; then DEV="$TSP_DEV"
elif [ -n "${TSP_IP:-}" ]; then DEV="root@$TSP_IP"
else DEV="root@192.168.1.25"; fi

SSH=(-o BatchMode=yes -o ConnectTimeout=8)
REMOTE_BACKUP="$ROOT/backups/visgrid-v18-room-traversal-$STAMP"
DEPLOY=0

rollback_on_error() {
    set +e
    if [ "$DEPLOY" = 1 ]; then
        echo "Attempting automatic V18 Lua rollback..."
        ssh "${SSH[@]}" "$DEV" "
          set -e
          test -s '$REMOTE_BACKUP/visgrid.lua.before-v18'
          cp -p '$REMOTE_BACKUP/visgrid.lua.before-v18' '$LUA'
          sync
        " || true
    fi
}

on_error() {
    rc=$?
    line=$1
    cmd=$2
    trap - ERR
    rollback_on_error
    {
      echo
      echo "=================================================================="
      echo "VISGRID V18 STOPPED SAFELY"
      echo "=================================================================="
      echo "Exit code: $rc"
      echo "Line: $line"
      echo "Command: $cmd"
      [ -f "$LOG" ] && {
          echo
          echo "----- install.log tail -----"
          tail -180 "$LOG" || true
      }
      echo
      echo "Package preserved: $PKG"
      echo "Device backup: $REMOTE_BACKUP"
    } | tee "$PKG/STOPPED_ERROR.txt"
    exit "$rc"
}
trap 'on_error "$LINENO" "$BASH_COMMAND"' ERR
exec > >(tee "$LOG") 2>&1

echo "=================================================================="
echo "OPENMW 0.51 TSP — VISGRID V18 ROOM-TRAVERSAL PVS"
echo "=================================================================="
echo
echo "NO rebuild."
echo "The exact proven V17 C++ PVS binary stays installed."
echo "The six-second load-safe hold stays installed."
echo

echo "===== 1/6 VERIFY EXACT PROVEN V17/V18 STATE ====="

if ssh "${SSH[@]}" "$DEV"   'pidof openmw-0.51 >/dev/null 2>&1 || pidof openmw >/dev/null 2>&1'
then
    echo "ERROR: OpenMW is running. Exit normally, then rerun."
    exit 20
fi

LIVE_BIN="$(ssh "${SSH[@]}" "$DEV" "sha256sum '$BIN'" | awk '{print $1}')"
LIVE_LUA="$(ssh "${SSH[@]}" "$DEV" "sha256sum '$LUA'" | awk '{print $1}')"
LIVE_TOPO="$(ssh "${SSH[@]}" "$DEV" "sha256sum '$TOPO'" | awk '{print $1}')"

echo "Binary  : $LIVE_BIN"
echo "Sensor  : $LIVE_LUA"
echo "Topology: $LIVE_TOPO"

[ "$LIVE_BIN" = "$BIN_SHA" ] || {
    echo "ERROR: exact proven V17 PVS binary is not active. ZERO changes."
    exit 21
}
[ "$LIVE_TOPO" = "$TOPO_SHA" ] || {
    echo "ERROR: tested Governor's Hall topology differs. ZERO changes."
    exit 22
}
if [ "$LIVE_LUA" != "$V17_SHA" ] && [ "$LIVE_LUA" != "$V18_SHA" ]; then
    echo "ERROR: sensor is neither exact V17 nor this exact V18. ZERO changes."
    exit 23
fi

ssh "${SSH[@]}" "$DEV" "
  grep -a -q 'TSP_INTERIOR_VISGRID_051_V5_TOPO_PVS' '$BIN'
  grep -Fq 'TSP_VISGRID_TOPOLOGY_V1' '$TOPO'
"
echo "PASS: known V17 PVS foundation verified."

echo
echo "===== 2/6 WRITE + VERIFY EXACT V18 SENSOR ====="

