base64 -d "$PKG/visgrid-v18.lua.b64" > "$PKG/visgrid-v18.lua"
rm -f "$PKG/visgrid-v18.lua.b64"

test "$(sha256sum "$PKG/visgrid-v18.lua" | awk '{print $1}')" = "$V18_SHA"
grep -Fq 'TSP_VISGRID_LUA_V18_ROOM_TRAVERSAL_PVS' "$PKG/visgrid-v18.lua"
grep -Fq 'TSP_VISGRID_V18_LOADSAFE_6S' "$PKG/visgrid-v18.lua"
grep -Fq 'POST_LOAD_ARM_DELAY = 6.0' "$PKG/visgrid-v18.lua"

echo "PASS: exact V18 sensor SHA=$V18_SHA"

echo
echo "===== 3/6 BACK UP LIVE SENSOR BEFORE EDIT ====="

ssh "${SSH[@]}" "$DEV" "
  set -e
  mkdir -p '$REMOTE_BACKUP'
  cp -p '$LUA' '$REMOTE_BACKUP/visgrid.lua.before-v18'
  cmp -s '$LUA' '$REMOTE_BACKUP/visgrid.lua.before-v18'
  sha256sum '$BIN' '$LUA' '$TOPO' > '$REMOTE_BACKUP/SHA256SUMS.before.txt'
  sync
"

scp "${SSH[@]}" -q   "$DEV:$REMOTE_BACKUP/visgrid.lua.before-v18"   "$PKG/device-backup/"

BACKUP_SHA="$(sha256sum "$PKG/device-backup/visgrid.lua.before-v18" | awk '{print $1}')"
[ "$BACKUP_SHA" = "$LIVE_LUA" ]

echo "PASS: exact live sensor backed up on device + Ubuntu."

echo
echo "===== 4/6 INSTALL LUA ONLY ====="

scp "${SSH[@]}" -q "$PKG/visgrid-v18.lua" "$DEV:/tmp/visgrid-v18.lua"
STAGE_SHA="$(ssh "${SSH[@]}" "$DEV" "sha256sum /tmp/visgrid-v18.lua" | awk '{print $1}')"
[ "$STAGE_SHA" = "$V18_SHA" ]

DEPLOY=1
ssh "${SSH[@]}" "$DEV" "
  set -e
  cp /tmp/visgrid-v18.lua '$LUA.new'
  mv -f '$LUA.new' '$LUA'
  rm -f /tmp/visgrid-v18.lua
  sync
"

INSTALLED_SHA="$(ssh "${SSH[@]}" "$DEV" "sha256sum '$LUA'" | awk '{print $1}')"
[ "$INSTALLED_SHA" = "$V18_SHA" ]

ssh "${SSH[@]}" "$DEV" "
  grep -Fq 'TSP_VISGRID_LUA_V18_ROOM_TRAVERSAL_PVS' '$LUA'
  grep -Fq 'POST_LOAD_ARM_DELAY = 6.0' '$LUA'
"

DEPLOY=0
echo "PASS: V18 Lua installed."

echo
echo "===== 5/6 VERIFY V17 ENGINE + TOPOLOGY UNCHANGED ====="

test "$(ssh "${SSH[@]}" "$DEV" "sha256sum '$BIN'" | awk '{print $1}')" = "$BIN_SHA"
test "$(ssh "${SSH[@]}" "$DEV" "sha256sum '$TOPO'" | awk '{print $1}')" = "$TOPO_SHA"

echo "PASS: proven V17 binary + topology byte-identical."

echo
echo "===== 6/6 WRITE HELPERS DIRECTLY IN ~/Downloads ====="

cat > "$HOME/Downloads/pull-visgrid-v18-pvs.sh" <<'EOF_PULL'
#!/usr/bin/env bash
set -Eeuo pipefail
ROOT="/mnt/SDCARD/data/ports/openmw51"
if [ -f "$HOME/Downloads/visgrid-tools/device.env" ]; then
    . "$HOME/Downloads/visgrid-tools/device.env" || true
fi
if [ -n "${TSP_DEV:-}" ]; then DEV="$TSP_DEV"
elif [ -n "${TSP_IP:-}" ]; then DEV="root@$TSP_IP"
else DEV="root@192.168.1.25"; fi
SSH=(-o BatchMode=yes -o ConnectTimeout=8)
STAMP="$(date +%Y%m%d-%H%M%S)"
OUT="$HOME/Downloads/visgrid-v18-pvs-trace-$STAMP.txt"

{
  echo "=================================================================="
  echo "VISGRID V18 ROOM-TRAVERSAL PVS TRACE"
  echo "=================================================================="
  echo "Ubuntu date: $(date)"
  ssh "${SSH[@]}" "$DEV" 'date; hostname'

  echo
  echo "===== V18 / PVS / VISGRID ====="
  ssh "${SSH[@]}" "$DEV" "
    grep -hE \
      'TSP_VISGRID_V18|TSP_VISGRID_V11|TSP_INTERIOR_VISGRID_051_V5_TOPO_PVS|TSP_INTERIOR_VISGRID|TSP_LOAD_FREEZE|Lua.*ERROR|Lua.*error' \
      '$ROOT/openmw_051_log.txt' '$ROOT/config-0.51/openmw.log' \
      2>/dev/null | tail -5000 || true
  "

  echo
  echo "===== PERF ====="
  ssh "${SSH[@]}" "$DEV" "
    [ -f '$ROOT/openmw51_perf_latest.txt' ] &&
      tail -1000 '$ROOT/openmw51_perf_latest.txt' || true
  "

  echo
  echo "===== HASHES ====="
  ssh "${SSH[@]}" "$DEV" "
    sha256sum \
      '$ROOT/bin/openmw-0.51' \
      '$ROOT/mods/TSPInteriorVisGrid/scripts/TSPInteriorVisGrid/visgrid.lua' \
      '$ROOT/mods/TSPInteriorVisGrid/scripts/TSPInteriorVisGrid/topology.lua' \
      2>/dev/null || true
  "
} 2>&1 | tee "$OUT"

echo
echo "Saved directly in Downloads:"
echo "  $OUT"

EOF_PULL
chmod +x "$HOME/Downloads/pull-visgrid-v18-pvs.sh"
bash -n "$HOME/Downloads/pull-visgrid-v18-pvs.sh"

cat > "$HOME/Downloads/rollback-visgrid-v18-pvs.sh" <<'EOF_ROLL'
#!/usr/bin/env bash
set -Eeuo pipefail
ROOT="/mnt/SDCARD/data/ports/openmw51"
if [ -f "$HOME/Downloads/visgrid-tools/device.env" ]; then
    . "$HOME/Downloads/visgrid-tools/device.env" || true
fi
if [ -n "${TSP_DEV:-}" ]; then DEV="$TSP_DEV"
elif [ -n "${TSP_IP:-}" ]; then DEV="root@$TSP_IP"
else DEV="root@192.168.1.25"; fi
SSH=(-o BatchMode=yes -o ConnectTimeout=8)

if ssh "${SSH[@]}" "$DEV" \
  'pidof openmw-0.51 >/dev/null 2>&1 || pidof openmw >/dev/null 2>&1'
then
    echo "ERROR: exit OpenMW normally before rollback."
    exit 20
fi

BACKUP="$(ssh "${SSH[@]}" "$DEV" \
  "ls -1dt '$ROOT'/backups/visgrid-v18-room-traversal-* 2>/dev/null | head -1")"
test -n "$BACKUP"

ssh "${SSH[@]}" "$DEV" "
  set -e
  test -s '$BACKUP/visgrid.lua.before-v18'
  cp -p '$BACKUP/visgrid.lua.before-v18' \
    '$ROOT/mods/TSPInteriorVisGrid/scripts/TSPInteriorVisGrid/visgrid.lua'
  sync
  sha256sum \
    '$ROOT/bin/openmw-0.51' \
    '$ROOT/mods/TSPInteriorVisGrid/scripts/TSPInteriorVisGrid/visgrid.lua'
"

echo "PASS: exact pre-V18 sensor restored."
echo "The proven V17 PVS binary was never changed."

EOF_ROLL
chmod +x "$HOME/Downloads/rollback-visgrid-v18-pvs.sh"
bash -n "$HOME/Downloads/rollback-visgrid-v18-pvs.sh"

cp -p "$HOME/Downloads/pull-visgrid-v18-pvs.sh" "$PKG/"
cp -p "$HOME/Downloads/rollback-visgrid-v18-pvs.sh" "$PKG/"

echo
echo "=================================================================="
echo "V18 ROOM-TRAVERSAL PVS INSTALLED"
echo "=================================================================="
echo
echo "What changed:"
echo "  - room/corridor baseline PVS is no longer the entire current floor"
echo "  - same-floor rooms behind mapped doors stay structurally culled"
echo "  - current room keeps open adjacency + stair connectors/endpoints"
echo "  - large rooms retain only embedded navmesh islands inside the chamber"
echo "  - room you just left stays enabled for 1.35s for smooth turn-back"
echo "  - mapped portals get a tiny physics probe fan"
echo "  - closed/blocked door => destination stays culled"
echo "  - clear/open portal => destination PVS opens immediately"
echo "  - portal wedge widens automatically as you approach"
echo "  - clear portal triggers ~0.9s full 14-ray acquisition burst"
echo "  - staircase keeps V17's proven endpoint-floor safety behavior"
echo "  - six-second load-safe hold unchanged"
echo
echo "Trace directly in Downloads:"
echo "  ~/Downloads/pull-visgrid-v18-pvs.sh"
echo
echo "Rollback directly in Downloads:"
echo "  ~/Downloads/rollback-visgrid-v18-pvs.sh"
echo
echo "New telemetry:"
echo "  pvsA = active structural sectors"
echo "  pvsR = C++ structural static rejection"
echo "  pvsN = recent/trailing room sectors"
echo "  pp   = targeted portal probe rays"
echo "  po   = portal probes that found clear depth"
